def find_changed_pairs(inputs, outputs):
    """Identify which (input, output) pairs actually differ."""
    changed = []
    for i, (inp, out) in enumerate(zip(inputs, outputs)):
        if inp != out:
            changed.append((i, inp, out))
    return changed

def find_minimal_edit(s_in, s_out):
    """Find the minimal edit operation needed to transform s_in to s_out."""
    # Simple implementation for now - looking for single character changes
    if len(s_in) == len(s_out):
        # Same length - look for single character difference
        diff_positions = []
        for i, (c1, c2) in enumerate(zip(s_in, s_out)):
            if c1 != c2:
                diff_positions.append(i)

        if len(diff_positions) == 1:
            pos = diff_positions[0]
            old_sub = s_in[pos:pos+1]
            new_sub = s_out[pos:pos+1]
            return old_sub, new_sub, pos

    # For insertions/deletions, we'll use a simpler approach
    # Let's check if we can find a substring replacement
    if len(s_in) > len(s_out):
        # Deletion case
        for i in range(len(s_in)):
            if i < len(s_out) and s_in[i] != s_out[i]:
                # Found first difference, check if deleting makes sense
                if s_in[i+1:] == s_out[i:]:
                    return s_in[i:i+1], "", i
    elif len(s_out) > len(s_in):
        # Insertion case  
        for i in range(len(s_in)):
            if s_in[i] != s_out[i]:
                # Found first difference, check if inserting makes sense
                if s_in[i:] == s_out[i+1:]:
                    return "", s_out[i:i+1], i
    else:
        # Same length - check if we can find a substring match
        for i in range(len(s_in)):
            for j in range(i+1, len(s_in)+1):
                sub_s_in = s_in[i:j]
                sub_s_out = s_out[i:j]
                if sub_s_in != sub_s_out:
                    return sub_s_in, sub_s_out, i

    # Default fallback
    return s_in, s_out, 0

def propose_rule_candidates(s_in, s_out):
    """Propose candidate rules based on the transformation."""
    # This is a simplified version - in practice this would be more sophisticated
    old_sub, new_sub, pos = find_minimal_edit(s_in, s_out)

    # Return the basic rule and a few variations
    candidates = [(old_sub, new_sub)]

    # Also try some variations for more general patterns
    if len(old_sub) > 1:
        # Try to make it more specific
        for i in range(1, len(old_sub)):
            candidates.append((old_sub[:i], new_sub[:i]))

    return candidates

def apply_rules(strings, rules):
    """Apply a sequence of replacement rules to strings."""
    result = strings[:]
    for pattern, replacement in rules:
        result = [s.replace(pattern, replacement) for s in result]
    return result

def score_rules(inputs, outputs, rules):
    """Score how well rules transform inputs to outputs."""
    transformed = apply_rules(inputs, rules)
    correct = sum(1 for i, o in zip(transformed, outputs) if i == o)
    return correct / len(inputs)

def find_over_applications(inputs, outputs, rules):
    """Find if any rules over-apply to strings that shouldn't change."""
    transformed = apply_rules(inputs, rules)
    over_apps = []
    for i, (orig, out) in enumerate(zip(inputs, outputs)):
        if orig != out and transformed[i] == out:
            # This is fine - the rule correctly transformed it
            pass
        elif orig == out and transformed[i] != out:
            # This is over-application - the rule changed something that should be unchanged
            over_apps.append((i, orig, transformed[i]))
    return over_apps

